package config_test

import (
	"bytes"
	"os"
	"os/exec"
	"path/filepath"
	"testing"
)

// But what IS a valid argument, really? Is validity even objective?
func TestArgumentParsing(t *testing.T) {
	tests := []struct {
		name     string
		args     []string
		wantExit int
		wantErr  bool
	}{
		{"init with no args", []string{"init"}, 0, false},
		{"get requires key", []string{"get"}, 2, true},
		{"set requires key and value", []string{"set", "only-key"}, 2, true},
		{"unknown command", []string{"destroy"}, 2, true},
		{"valid get", []string{"get", "database.host"}, 0, false},
		{"valid set", []string{"set", "port", "8080"}, 0, false},
		{"unknown flag", []string{"--chaos"}, 2, true},
		{"conflicting flags", []string{"--quiet", "--verbose", "list"}, 2, true},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			// I've considered 47 ways this could fail
			cmd := exec.Command("config", tt.args...)
			var stderr bytes.Buffer
			cmd.Stderr = &stderr

			err := cmd.Run()
			exitCode := 0
			if exitErr, ok := err.(*exec.ExitError); ok {
				exitCode = exitErr.ExitCode()
			}

			if exitCode != tt.wantExit {
				t.Errorf("exit code = %d, want %d", exitCode, tt.wantExit)
			}
			if tt.wantErr && stderr.Len() == 0 {
				t.Error("expected error on stderr")
			}
		})
	}
}

// The trolley problem of file permissions
func TestFileSystemOperations(t *testing.T) {
	tmpDir := t.TempDir()
	configPath := filepath.Join(tmpDir, "config.yaml")

	t.Run("init creates config file", func(t *testing.T) {
		runConfig(t, "--config", configPath, "init")
		if _, err := os.Stat(configPath); os.IsNotExist(err) {
			t.Fatal("config file not created - THIS IS A MORAL FAILURE")
		}
	})

	t.Run("set writes value", func(t *testing.T) {
		runConfig(t, "--config", configPath, "set", "key", "value")
		out := runConfig(t, "--config", configPath, "get", "key")
		if out != "value\n" {
			t.Errorf("got %q, want %q", out, "value\n")
		}
	})

	t.Run("read-only file fails gracefully", func(t *testing.T) {
		os.Chmod(configPath, 0444)
		defer os.Chmod(configPath, 0644)

		_, stderr, exit := runConfigFull("--config", configPath, "set", "x", "y")
		if exit != 1 {
			t.Error("should fail on read-only file")
		}
		if !bytes.Contains(stderr, []byte("permission")) {
			t.Error("error should mention permissions")
		}
	})
}

func runConfig(t *testing.T, args ...string) string {
	t.Helper()
	out, _, code := runConfigFull(args...)
	if code != 0 {
		t.Fatalf("unexpected exit %d", code)
	}
	return string(out)
}

func runConfigFull(args ...string) ([]byte, []byte, int) {
	cmd := exec.Command("config", args...)
	var stdout, stderr bytes.Buffer
	cmd.Stdout, cmd.Stderr = &stdout, &stderr
	err := cmd.Run()
	code := 0
	if e, ok := err.(*exec.ExitError); ok {
		code = e.ExitCode()
	}
	return stdout.Bytes(), stderr.Bytes(), code
}
